local EMBEDDED = 8
local function compile(code, name)
    local f, err
    if setfenv then
        f, err = loadstring(code, name)
        if f then setfenv(f, getfenv(1)) end
    else
        f, err = load(code, name, "t", _ENV)
    end
    return f, err
end
local function cachedBuild()
    local text, file
    pcall(function()
        local ctx = activity or service or this
        file = luajava.newInstance("java.io.File", ctx.getFilesDir(), "tournament_core.lua")
        if not file.exists() then return end
        local br = luajava.newInstance("java.io.BufferedReader", luajava.newInstance("java.io.InputStreamReader", luajava.newInstance("java.io.FileInputStream", file), "UTF-8"))
        local lines, line = {}, br.readLine()
        while line ~= nil do lines[#lines + 1] = line; line = br.readLine() end
        br.close()
        local t = table.concat(lines, "\n")
        local v = tonumber(t:match("local APP_VERSION = (%d+)"))
        if v and v > EMBEDDED then text = t end
    end)
    return text, file
end
local function run(...)
    local name = "=main"
    pcall(function() name = debug.getinfo(1, "S").source or name end)
    local fromCache = false
    pcall(function() fromCache = TS_FROM_CACHE and true or false end)
    if not fromCache then
        local text, file = cachedBuild()
        if text then
            local f = compile(text, name)
            if f then
                pcall(function() TS_FROM_CACHE = true end)
                local ok = pcall(f, ...)
                pcall(function() TS_FROM_CACHE = nil end)
                if ok then return end
            end
            pcall(function() file.delete() end)
        end
    end
    local key = table.concat(K)
    local seed = 7
    for i = 1, #key do seed = (seed * 31 + key:byte(i)) % 2147483647 end
    if seed == 0 then seed = 1 end
    local prev = 0
    local code = P:gsub("%s+", ""):gsub("%x%x", function(h)
        seed = (seed * 16807) % 2147483647
        local k = math.floor(seed / 256) % 256
        local c = tonumber(h, 16)
        local p = (c - k - prev) % 256
        prev = c
        return string.char(p)
    end)
    local f, err = compile(code, name)
    if not f then error(err) end
    return f(...)
end
return run(...)
